let today=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Moscow'}).format(new Date());let selected=today,anchor=new Date(today+'T12:00:00'),view='today',mode=matchMedia('(min-width:900px)').matches?'week':'day',ready=false,busy=false,sync='Подключение…';anchor.setDate(anchor.getDate()-weekday(today));
