const sheet=$('#modal'),closeDialog=sheet.close.bind(sheet),scrim=document.createElement('div');scrim.id='scrim';document.body.insertBefore(scrim,sheet);scrim.onclick=()=>sheet.close();
const closeNow=()=>{closeDialog();scrim.classList.remove('on');document.documentElement.classList.remove('sheet-open')};let closeTimer=null;
