function modal(html){const m=$('#modal');if(closeTimer){clearTimeout(closeTimer);closeTimer=null;m.classList.remove('closing')}if(!m.open)history.pushState({modal:true},'');m.innerHTML=`<button class="close" data-close aria-label="Закрыть">×</button>${html}`;if(!m.open){document.documentElement.classList.add('sheet-open');m.show();scrim.classList.add('on')}m.querySelector('[data-close]').onclick=()=>m.close()}
let closing=false;
$('#modal').addEventListener('close',()=>{if(history.state?.modal){closing=true;history.back()}});
function go(next){if(next===view)return;if(view==='today')history.pushState({view:next},'');else history.replaceState({view:next},'');view=next;render();window.scrollTo(0,0)}
window.addEventListener('popstate',()=>{if(closing){closing=false;return}if($('#modal').open){$('#modal').close();return}if(view!=='today'){view='today';render()}});
// Кнопка «Назад» Android: true — шаг назад обработан внутри приложения.
window.ritmBack=()=>{if($('#modal').open){$('#modal').close();return true}if(view!=='today'&&store.session()){view='today';history.replaceState(null,'');render();window.scrollTo(0,0);return true}return false};
async function commit(next,msg){if(busy)return false;busy=true;try{await store.save(next,msg);$('#modal').close();native.haptic('confirm');notify('Сохранено · '+(store.cloud?'в облаке':'на этом устройстве'));render();return true}catch(e){notify(e.message);return false}finally{busy=false}}
function nowMinutes(){const s=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Moscow',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date());const [h,m]=s.split(':').map(Number);return h*60+m+(h<9?1440:0)}
// До 09:00 МСК идёт завершение предыдущего дня плана: 00:15 относится ко вчерашнему расписанию.
function planDay(){const h=Number(new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Moscow',hour:'2-digit',hour12:false}).format(new Date()))%24;if(h>=9)return today;const d=new Date(today+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-1);return d.toISOString().slice(0,10)}
// Начатое и не завершённое занятие остаётся текущим (переработка), но не дольше часа после его конца.
function current(){const blocks=dayPlan(planDay()),m=nowMinutes();const active=blocks.find(b=>b.actualStart&&!b.actualEnd&&b.start<=m&&m<b.end+60);return active||blocks.find(b=>b.start<=nowMinutes()&&b.end>nowMinutes())}
const kinds={work:'Работа',sport:'Спорт',together:'Вместе',personal:'Для себя',meal:'Обед / отдых',sleep:'Подготовка ко сну'};
function nextBlock(c){const m=nowMinutes(),after=c?Math.max(m,c.end):m;return dayPlan(planDay()).find(b=>b!==c&&b.start>=after&&!b.actualEnd)}
function moreView(){const owner=store.getRole()==='owner';const item=(v,t,sub,i)=>`<button class="more-item" data-view="${v}">${icon(i)}<span><strong>${t}</strong><small>${sub}</small></span>${icon('arrow')}</button>`;const th=(()=>{try{return localStorage.getItem('ritm-theme')||'auto'}catch{return 'auto'}})(),lite=document.documentElement.hasAttribute('data-lite');return `<section class="hello"><p class="eyebrow">Ещё</p><h1>Всё остальное</h1></section><section class="card more-list">${owner?item('sleep','Дневник сна','Когда лёг, когда проснулся, качество','moon'):''}${owner?item('proposals','Предложения','Активности, которые предлагают вам','together'):''}${owner?item('history','История изменений','Все переносы и отметки календаря','history'):''}${item('scenarios','Сценарии','Обмен среды и четверга, вело вместо зала','spark')}${item('settings','Уведомления','Напоминания, карточка дня, разрешения Android','bell')}${item('access','Профиль и доступ','Вход, выход, резервная копия','users')}</section><section class="card section settings-list"><h2>Оформление</h2><p class="subtle">Действует на этом устройстве.</p><div class="segments" role="group" aria-label="Тема">${[['auto','Системная'],['light','Светлая'],['dark','Тёмная']].map(([k,t])=>`<button data-theme-set="${k}" class="${th===k?'selected':''}" aria-pressed="${th===k}">${t}</button>`).join('')}</div><label class="switch"><span><strong>Облегчённые эффекты</strong><small>Без размытия и анимации карточек — быстрее на слабых телефонах.</small></span><input type="checkbox" id="lite" ${lite?'checked':''}><i aria-hidden="true"></i></label></section>`}
// Сохраняет состояние нативных напоминаний и карточки после любого изменения данных.
function syncNative(restore=false){const loggedIn=Boolean(store.session());if(loggedIn){native.inboxStart(store.publicConfig);const own=store.getRole()==='owner',seen=store.proposals.map(p=>own?p.created_at:p.decided_at).filter(Boolean).sort().pop();if(seen)native.inboxSeen(seen)}return reminders.sync({dayPlan,today,role:store.getRole(),health:store.health,sleep:store.data.sleep,sleepOpen:store.sleepOpen,loggedIn},restore)}
const mskInput=d=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Moscow',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(d).replace(' ','T');
const fromMsk=v=>v?new Date(v+':00+03:00').toISOString():null;
const savedText=r=>r.queued?'Сохранено на телефоне · отправится при появлении сети':store.cloud?'Сохранено в облаке':'Сохранено на этом устройстве';
