function addDialog(backlogIndex){if(!canEdit())return;const source=backlogIndex!==undefined?store.data.backlog[backlogIndex]:null;modal(`<h2>${source?'Вернуть занятие в план':'Новое занятие'}</h2><form id="add-form"><label>Название<input name="title" maxlength="100" required value="${esc(source?.title||'')}"></label><label>Дата<input name="date" type="date" required value="${selected}"></label><div class="form-row"><label>Начало<input name="start" type="time" value="19:00" required></label><label>Длительность, мин<input name="duration" type="number" min="5" max="900" value="${source?source.end-source.start:60}" required></label></div><label>Категория<select name="kind">${Object.entries(kinds).map(([k,v])=>`<option value="${k}" ${source?.kind===k?'selected':''}>${v}</option>`).join('')}</select></label><button class="primary">Посмотреть новый план</button></form>`);$('#add-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),d=f.get('date'),start=minutes(f.get('start'));let blocks=structuredClone(dayPlan(d));const overlap=blocks.find(b=>b.start<start&&b.end>start);if(overlap){if(overlap.locked||overlap.kind==='sleep')return notify(overlap.locked?'Это время занято созвоном':'Это время подготовки ко сну, оно не меняется');overlap.end=start}const b={id:crypto.randomUUID(),title:f.get('title'),start,end:start+Number(f.get('duration')),kind:f.get('kind')};blocks.push(b);blocks.sort((a,b)=>a.start-b.start);try{const r=reflow(blocks,b.id,start,b.end-start);applyDay(d,r.blocks,r.deferred,`${d}: добавлено «${b.title}»`,{removeIndex:backlogIndex,from:start,own:b.id})}catch(e){notify(e.message)}}}
